"""ids_of every element of a project: print id, category, name and some fields of the element."""
import sys, subprocess, json
ORIG = '/workspace/executable'
f = sys.argv[1]
d = json.load(open(f))
ids = [int(k) for k in d['elements']]
p = subprocess.run([ORIG, 'run', f, '--cmd', 'ids_of ' + json.dumps({'ids': ids})], capture_output=True, cwd='/tmp/notes-agent/work')
out = p.stdout.decode().strip().split('\n')
v = json.loads(out[-1])
lib = d['library']
gl = {e['guid']: e for e in lib.values()}
