#!/usr/bin/env python3
"""Find wall face corner points (and centre-line end points) in the original via linear dimensions from a grid start
at (-100000,-100000).
usage: corner.py setupfile wallid [wallid...]  (setup lines are commands; the grid is added first, id 100002)"""
import sys, subprocess, json
ORIG = '/workspace/executable'
setup = [l.strip() for l in open(sys.argv[1]) if l.strip() and not l.startswith('#')]
walls = [int(x) for x in sys.argv[2:]]
G = -100000.0
cmds = ['grid {"start":[-100000,-100000],"end":[-100000,-90000]}'] + setup
q = []
for w in walls:
    for face in ('left', 'right', 'centre'):
        for pt in ('start', 'end'):
            for orient in ('horizontal', 'vertical'):
                cmds.append('dimension ' + json.dumps({"refs": [{"id": 100002, "point": "start"}, {"id": w, "face": face, "point": pt}], "at": [-100000, -100000], "kind": "linear", "orient": orient}))
                q.append((w, face, pt, orient))
cmds.append('elements {"category":"dimension"}')
args = [ORIG, 'run']
for c in cmds: args += ['--cmd', c]
p = subprocess.run(args, capture_output=True, cwd='/tmp/notes-agent/work')
out = p.stdout.decode().strip().split('\n')
if p.stderr: print('ERR', p.stderr.decode().strip())
v = json.loads(out[-1])
vals = [e['values'][0] for e in v['elements']]
res = {}
for (w, face, pt, orient), val in zip(q, vals):
    res.setdefault((w, face, pt), [None, None])[0 if orient == 'horizontal' else 1] = G + val
for (w, face, pt), xy in res.items():
    print(w, face, pt, [round(c, 3) for c in xy])

