//! Plan geometry the notes read: points and directions, walls' faces (by their location line, their
//! type's layers and the joins at their ends), the openings in them, grids and detail lines as the
//! lines and arcs a dimension measures to.

use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, Ctx};
use std::collections::HashMap;
use std::rc::Rc;

pub type P = [f64; 2];

pub fn add(a: P, b: P) -> P {
    [a[0] + b[0], a[1] + b[1]]
}
pub fn sub(a: P, b: P) -> P {
    [a[0] - b[0], a[1] - b[1]]
}
pub fn mul(a: P, k: f64) -> P {
    [a[0] * k, a[1] * k]
}
pub fn dot(a: P, b: P) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
pub fn cross(a: P, b: P) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
pub fn len(a: P) -> f64 {
    a[0].hypot(a[1])
}
pub fn dist(a: P, b: P) -> f64 {
    len(sub(b, a))
}
pub fn unit(a: P) -> P {
    let l = len(a);
    if l == 0.0 {
        [0.0, 0.0]
    } else {
        [a[0] / l, a[1] / l]
    }
}
/// The direction a quarter turn counter-clockwise from `a` (to its left).
pub fn left(a: P) -> P {
    [-a[1], a[0]]
}
pub fn lerp(a: P, b: P, t: f64) -> P {
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}
/// Where the lines through `p` along `d` and through `q` along `e` cross.
pub fn meet(p: P, d: P, q: P, e: P) -> Option<P> {
    let den = cross(d, e);
    if den.abs() < 1e-12 {
        return None;
    }
    let t = cross(sub(q, p), e) / den;
    Some(add(p, mul(d, t)))
}

pub fn pt(v: Option<&Value>) -> Option<P> {
    let a = v?.as_arr()?;
    if a.len() < 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

pub fn pval(p: P) -> Value {
    Value::Arr(vec![Value::f(p[0]), Value::f(p[1])])
}

// ---------------------------------------------------------------- arcs

/// A circular arc from `a` to `b` turning `turn` degrees counter-clockwise (negative: clockwise).
#[derive(Clone, Copy, Debug)]
pub struct Arc {
    pub c: P,
    pub r: f64,
    /// The angle of its start from its centre, and how far it turns (radians, signed).
    pub a0: f64,
    pub sweep: f64,
}

impl Arc {
    pub fn from_chord(a: P, b: P, turn_deg: f64) -> Option<Arc> {
        let t = turn_deg.to_radians();
        let chord = dist(a, b);
        if t.abs() < 1e-12 || chord == 0.0 {
            return None;
        }
        let r = chord / (2.0 * (t / 2.0).sin().abs());
        let m = lerp(a, b, 0.5);
        let d = unit(sub(b, a));
        // the centre lies to the left of a→b for a counter-clockwise turn under a half circle
        let h = (r * r - chord * chord / 4.0).max(0.0).sqrt();
        let side = if (t.abs() < std::f64::consts::PI) == (t > 0.0) { 1.0 } else { -1.0 };
        let c = add(m, mul(left(d), h * side));
        let a0 = (a[1] - c[1]).atan2(a[0] - c[0]);
        Some(Arc { c, r, a0, sweep: t })
    }
    pub fn at(&self, f: f64) -> P {
        let ang = self.a0 + self.sweep * f;
        [self.c[0] + self.r * ang.cos(), self.c[1] + self.r * ang.sin()]
    }
    pub fn length(&self) -> f64 {
        self.r * self.sweep.abs()
    }
    /// The same arc moved `off` toward its left (of its way along): smaller round a counter-clockwise arc.
    pub fn offset(&self, off: f64) -> Arc {
        let r = if self.sweep > 0.0 { self.r - off } else { self.r + off };
        Arc { r, ..*self }
    }
}

// ---------------------------------------------------------------- walls

/// A wall as the notes measure it: its location line, its faces and their ends after joins.
#[derive(Clone, Debug)]
pub struct Wall {
    pub id: u64,
    pub level: String,
    pub a: P,
    pub b: P,
    pub d: P,
    pub n: P,
    pub length: f64,
    pub t: f64,
    /// How far its left and right faces lie to the left of its location line.
    pub left: f64,
    pub right: f64,
    pub arc: Option<Arc>,
    /// Its faces' corners after the joins at its ends: [left start, left end, right start, right end].
    pub corners: [P; 4],
}

impl Wall {
    pub fn centre_off(&self) -> f64 {
        (self.left + self.right) / 2.0
    }
    /// The line of a face (`left`, `right`, `centre`): a point on it.
    pub fn face_point(&self, face: &str) -> P {
        let off = match face {
            "left" => self.left,
            "right" => self.right,
            _ => self.centre_off(),
        };
        add(self.a, mul(self.n, off))
    }
    pub fn face_arc(&self, face: &str) -> Option<Arc> {
        let off = match face {
            "left" => self.left,
            "right" => self.right,
            _ => self.centre_off(),
        };
        self.arc.map(|a| a.offset(off))
    }
    /// A face's end: a corner after joins (left, right), or the centre line's.
    pub fn face_end(&self, face: &str, end: bool) -> P {
        match face {
            "left" => self.corners[if end { 1 } else { 0 }],
            "right" => self.corners[if end { 3 } else { 2 }],
            _ => {
                if let Some(a) = self.face_arc("centre") {
                    return a.at(if end { 1.0 } else { 0.0 });
                }
                let off = mul(self.n, self.centre_off());
                add(if end { self.b } else { self.a }, off)
            }
        }
    }
    /// How far along it (from its start) its start or end face lies: the farthest its faces reach.
    pub fn end_along(&self, end: bool) -> f64 {
        if end {
            dot(sub(self.corners[1], self.a), self.d).max(dot(sub(self.corners[3], self.a), self.d))
        } else {
            dot(sub(self.corners[0], self.a), self.d).min(dot(sub(self.corners[2], self.a), self.d))
        }
    }
}

/// A wall type's thickness and where its core lies: the thickness of its layers outside the core
/// and of the core (the structure layers and what lies between them; the whole wall without layers).
pub fn wall_type_dims(def: &Value) -> (f64, f64, f64) {
    let t = common::num(def, "thickness").unwrap_or(0.0);
    let layers: Vec<(String, f64)> = def
        .get("layers")
        .and_then(|l| l.as_arr())
        .map(|a| {
            a.iter()
                .map(|l| (common::text(l, "function").unwrap_or("").to_string(), common::num(l, "thickness").unwrap_or(0.0)))
                .collect()
        })
        .unwrap_or_default();
    if layers.is_empty() {
        return (t, 0.0, t);
    }
    let first = layers.iter().position(|(f, _)| f == "structure");
    let last = layers.iter().rposition(|(f, _)| f == "structure");
    match (first, last) {
        (Some(i), Some(j)) => {
            let ext: f64 = layers[..i].iter().map(|l| l.1).sum();
            let core: f64 = layers[i..=j].iter().map(|l| l.1).sum();
            (t, ext, core)
        }
        _ => (t, 0.0, t),
    }
}

/// The wall without its joins: its line, faces and square ends.
fn bare_wall(pr: &Project, id: u64, e: &Value) -> Option<Wall> {
    let a = pt(e.get("start"))?;
    let b = pt(e.get("end"))?;
    let (t, ext, core) = common::element_type(pr, e).map(|(_, def)| wall_type_dims(def)).unwrap_or((0.0, 0.0, 0.0));
    // the exterior is the wall's left side
    let left = match common::text(e, "location").unwrap_or("centre") {
        "exterior-finish" => 0.0,
        "interior-finish" => t,
        "core-centre" => ext + core / 2.0,
        "exterior-core" => ext,
        "interior-core" => ext + core,
        _ => t / 2.0,
    };
    let right = left - t;
    let d = unit(sub(b, a));
    let n = left_of(d);
    let arc = common::num(e, "arc").filter(|x| *x != 0.0).and_then(|t| Arc::from_chord(a, b, t));
    let length = match &arc {
        Some(c) => c.length(),
        None => dist(a, b),
    };
    let mut w = Wall {
        id,
        level: common::text(e, "level").unwrap_or("").to_string(),
        a,
        b,
        d,
        n,
        length,
        t,
        left,
        right,
        arc,
        corners: [[0.0; 2]; 4],
    };
    if let Some(c) = arc {
        let l = c.offset(left);
        let r = c.offset(right);
        w.corners = [l.at(0.0), l.at(1.0), r.at(0.0), r.at(1.0)];
    } else {
        w.corners = [add(a, mul(n, left)), add(b, mul(n, left)), add(a, mul(n, right)), add(b, mul(n, right))];
    }
    Some(w)
}

fn left_of(d: P) -> P {
    left(d)
}

/// How near two walls' ends are to be joined.
const JOIN_TOL: f64 = 1.0;

/// Every wall of the project with its joins worked out, by id.
pub fn walls(cx: &Ctx) -> Rc<HashMap<u64, Wall>> {
    cx.cached("notes:walls", || Rc::new(make_walls(cx.pr)))
}

pub fn wall(cx: &Ctx, id: u64) -> Option<Wall> {
    walls(cx).get(&id).cloned()
}

fn make_walls(pr: &Project) -> HashMap<u64, Wall> {
    let mut bare: Vec<Wall> = Vec::new();
    for (id, e) in &pr.elements {
        if common::category(e) == "wall" {
            if let Some(w) = bare_wall(pr, *id, e) {
                bare.push(w);
            }
        }
    }
    let mut out = HashMap::new();
    for w in &bare {
        let mut j = w.clone();
        if w.arc.is_none() {
            for end in [false, true] {
                join_end(&bare, w, &mut j, end);
            }
        }
        out.insert(w.id, j);
    }
    out
}

/// The wall's end at `end`: (its point, its direction pointing away from the wall's body).
fn end_of(w: &Wall, end: bool) -> (P, P) {
    if end {
        (w.b, w.d)
    } else {
        (w.a, mul(w.d, -1.0))
    }
}

/// A face line of `w` as seen from one of its ends going away from its body: (point, direction) of
/// the face that is on the left when walking out of the wall through that end.
fn face_line(w: &Wall, end: bool, left_side: bool) -> (P, P) {
    // walking out through the end: along d at the end, against d at the start
    let (_, out) = end_of(w, end);
    let off = if end == left_side { w.left } else { w.right };
    (add(w.a, mul(w.n, off)), out)
}

fn set_corner(j: &mut Wall, end: bool, left_face: bool, p: P) {
    let k = match (left_face, end) {
        (true, false) => 0,
        (true, true) => 1,
        (false, false) => 2,
        (false, true) => 3,
    };
    j.corners[k] = p;
}

fn join_end(all: &[Wall], w: &Wall, j: &mut Wall, end: bool) {
    let (p, out) = end_of(w, end);
    if w.length == 0.0 {
        return;
    }
    // the other walls ending at this end
    let mut mates: Vec<(&Wall, bool)> = Vec::new();
    for o in all {
        if o.id == w.id || o.level != w.level || o.arc.is_some() || o.length == 0.0 {
            continue;
        }
        if dist(o.a, p) <= JOIN_TOL {
            mates.push((o, false));
        } else if dist(o.b, p) <= JOIN_TOL {
            mates.push((o, true));
        }
    }
    if mates.len() == 1 {
        let (m, mend) = mates[0];
        let (_, mout) = end_of(m, mend);
        // walking out of w through p and into m: w's left face goes on as m's right face seen
        // walking out of m through its end (it is walked the other way)
        let mut corners = Vec::new();
        for left_side in [true, false] {
            let (fp, fd) = face_line(w, end, left_side);
            let (mp, md) = face_line(m, mend, !left_side);
            let c = meet(fp, fd, mp, md);
            corners.push(c);
        }
        let ok = corners.iter().all(|c| c.is_some()) && {
            let ext: Vec<f64> = corners.iter().map(|c| dot(sub(c.unwrap(), p), out)).collect();
            ext.iter().all(|e| e.abs() <= w.t.max(m.t) + 1e-9)
        };
        let _ = mout;
        if ok {
            for (i, left_side) in [true, false].iter().enumerate() {
                let face_is_left = end == *left_side;
                set_corner(j, end, face_is_left, corners[i].unwrap());
            }
        }
        return;
    }
    if mates.len() == 2 {
        // two of the three running on as one wall: the third abuts them
        let dirs: Vec<P> = mates.iter().map(|(m, me)| end_of(m, *me).1).collect();
        let straight = |a: P, b: P| dot(a, b) < -0.999_999;
        if straight(out, dirs[0]) || straight(out, dirs[1]) {
            // w runs on through: the abutting wall is the other one
            let (other, oend) = if straight(out, dirs[0]) { mates[1] } else { mates[0] };
            let (_, oout) = end_of(other, oend);
            // the abutting wall comes in on w's side where its body lies
            let side_left = dot(mul(oout, -1.0), w.n) > 0.0;
            // that face of w ends at the abutting wall's face on its side
            let face_off = if side_left { w.left } else { w.right };
            let fp = add(w.a, mul(w.n, face_off));
            // the abutting wall's faces: the one nearer w's body
            let lp = add(other.a, mul(other.n, other.left));
            let rp = add(other.a, mul(other.n, other.right));
            let pick = |q: P| dot(sub(q, p), mul(out, -1.0));
            let face = if pick(lp) > pick(rp) { lp } else { rp };
            if let Some(c) = meet(fp, w.d, face, other.d) {
                set_corner(j, end, side_left, c);
            }
            return;
        }
        if straight(dirs[0], dirs[1]) {
            // w abuts the two running on: cut at their face on its side
            let (h, _) = mates[0];
            cut_at_host(w, j, end, h);
        }
        return;
    }
    if !mates.is_empty() {
        return;
    }
    // a wall it ends inside
    for o in all {
        if o.id == w.id || o.level != w.level || o.arc.is_some() || o.length == 0.0 {
            continue;
        }
        let along = dot(sub(p, o.a), o.d);
        let across = dot(sub(p, o.a), o.n);
        if along > 0.0 && along < o.length && across <= o.left + 1e-9 && across >= o.right - 1e-9 {
            cut_at_host(w, j, end, o);
            return;
        }
    }
}

/// The end of `w` cut at the face of `h` on the side its body comes from.
fn cut_at_host(w: &Wall, j: &mut Wall, end: bool, h: &Wall) {
    let (p, out) = end_of(w, end);
    let lp = add(h.a, mul(h.n, h.left));
    let rp = add(h.a, mul(h.n, h.right));
    // the face toward the rest of w
    let back = mul(out, -1.0);
    let face = if dot(sub(lp, p), back) > dot(sub(rp, p), back) { lp } else { rp };
    for face_left in [true, false] {
        let off = if face_left { w.left } else { w.right };
        let fp = add(w.a, mul(w.n, off));
        if let Some(c) = meet(fp, w.d, face, h.d) {
            set_corner(j, end, face_left, c);
        }
    }
}

// ---------------------------------------------------------------- openings

/// A door's or window's width: its type's, its family type's or its family's `Width`, or one of
/// its own.
pub fn opening_width(pr: &Project, e: &Value) -> Option<f64> {
    if let Some(w) = e.get("params").and_then(|p| p.get("Width")).and_then(|w| w.as_f64()) {
        return Some(w);
    }
    if let Some(fg) = common::text(e, "family") {
        let (fname, fam) = common::family(pr, fg)?;
        let tname = common::text(e, "type").and_then(|g| common::family_type(pr, &fname, g));
        if let Some(tn) = tname {
            if let Some(w) = fam.get("types").and_then(|t| t.get(&tn)).and_then(|t| t.get("Width")).and_then(|w| w.as_f64()) {
                return Some(w);
            }
        }
        let params = fam.get("parameters")?.as_arr()?;
        for p in params {
            if common::text(p, "name") == Some("Width") {
                return common::num(p, "value");
            }
        }
        return None;
    }
    let (_, def) = common::element_type(pr, e)?;
    common::num(def, "width")
}

/// Where a door or window stands on its wall's location line, and the wall's way there.
pub fn opening_place(cx: &Ctx, e: &Value) -> Option<(P, P, Wall)> {
    let (hid, _) = common::target(cx.pr, e, "host")?;
    let w = wall(cx, hid)?;
    let off = common::num(e, "offset").unwrap_or(0.0);
    if let Some(a) = w.arc {
        let f = if a.length() == 0.0 { 0.0 } else { off / a.length() };
        let p = a.at(f);
        let ang = a.a0 + a.sweep * f;
        let tan = if a.sweep > 0.0 { [-ang.sin(), ang.cos()] } else { [ang.sin(), -ang.cos()] };
        return Some((p, tan, w));
    }
    Some((add(w.a, mul(w.d, off)), w.d, w))
}

//! Lengths as drawings letter them: in the project's units (mm, cm, m, fractional inches, decimal
//! feet, feet and fractional inches) or a dimension type's own, to its decimals.

use crate::project::Project;

/// The project's length units.
pub fn project_units(pr: &Project) -> String {
    pr.get("units").and_then(|v| v.as_str()).unwrap_or("mm").to_string()
}

fn round_to(x: f64, decimals: u32) -> f64 {
    let k = 10f64.powi(decimals as i32);
    (x * k).round() / k
}

/// Rust's shortest display of a number (`100` for 100.0, `123.5`), no sign on zero.
pub fn shortest(x: f64) -> String {
    let x = if x == 0.0 { 0.0 } else { x };
    format!("{}", x)
}

fn fixed(x: f64, decimals: u32) -> String {
    let v = round_to(x, decimals);
    let v = if v == 0.0 { 0.0 } else { v };
    format!("{:.*}", decimals as usize, v)
}

fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

/// Sixteenths of an inch, `n` of them, as a fraction (`3/8`), or None for none.
fn fraction(n: i64) -> Option<String> {
    if n == 0 {
        return None;
    }
    let g = gcd(n, 16);
    Some(format!("{}/{}", n / g, 16 / g))
}

/// Inches to the nearest sixteenth: `39 3/8"`, `1/8"`, `0"`.
fn inches(mm: f64) -> String {
    let n = (mm / 25.4 * 16.0).round() as i64;
    let neg = n < 0;
    let n = n.abs();
    let whole = n / 16;
    let frac = fraction(n % 16);
    let s = match (whole, frac) {
        (0, Some(f)) => format!("{}\"", f),
        (w, Some(f)) => format!("{} {}\"", w, f),
        (w, None) => format!("{}\"", w),
    };
    if neg {
        format!("-{}", s)
    } else {
        s
    }
}

/// Feet and inches to the nearest sixteenth: `3'-3 3/8"`, `0'-0 1/8"`, `10'-0"`.
fn feet_inches(mm: f64) -> String {
    let n = (mm / 25.4 * 16.0).round() as i64;
    let neg = n < 0;
    let n = n.abs();
    let feet = n / 192;
    let rem = n % 192;
    let whole = rem / 16;
    let s = match fraction(rem % 16) {
        Some(f) => format!("{}'-{} {}\"", feet, whole, f),
        None => format!("{}'-{}\"", feet, whole),
    };
    if neg {
        format!("-{}", s)
    } else {
        s
    }
}

/// A length in mm as a drawing letters it in `units`, to `decimals` where they're given (decimal
/// units only).
pub fn length_text(mm: f64, units: &str, decimals: Option<u64>) -> String {
    let d = decimals.map(|d| d.min(12) as u32);
    match units {
        "cm" => match d {
            Some(d) => fixed(mm / 10.0, d),
            None => shortest(round_to(mm / 10.0, 1)),
        },
        "m" => fixed(mm / 1000.0, d.unwrap_or(2)),
        "in" => inches(mm),
        "ft" => format!("{}'", fixed(mm / 304.8, d.unwrap_or(2))),
        "ft-in" => feet_inches(mm),
        _ => fixed(mm, d.unwrap_or(0)),
    }
}

//! Dimensions as `elements` shows them: their type's name, the lengths (or angle, radius…) they
//! measure, and their text as it is lettered.

use super::geo::{self, Arc, P};
use super::units;
use crate::json::Value;
use crate::readers::common::{self, r2, Ctx};

/// What a dimension's reference is in plan.
#[derive(Clone, Copy, Debug)]
pub enum Geo {
    /// A line through a point along a direction.
    Line(P, P),
    Point(P),
    Circle(P, f64),
    Arc(Arc),
}

fn ref_str<'a>(r: &'a Value, k: &str) -> Option<&'a str> {
    r.get(k).and_then(|v| v.as_str())
}

/// The plan geometry a stored reference `{id, face, point?}` stands for.
pub fn resolve(cx: &Ctx, r: &Value) -> Option<Geo> {
    let pr = cx.pr;
    let g = ref_str(r, "id")?;
    let (id, e) = common::by_guid(pr, g)?;
    let face = ref_str(r, "face").unwrap_or("centre");
    let point = ref_str(r, "point");
    match common::category(e) {
        "wall" => {
            let w = geo::wall(cx, id)?;
            if let Some(pt) = point {
                let end = pt == "end";
                return Some(Geo::Point(match face {
                    "start" | "end" => w.face_end("centre", end),
                    f => w.face_end(f, end),
                }));
            }
            match face {
                "start" | "end" => {
                    let along = w.end_along(face == "end");
                    Some(Geo::Line(geo::add(w.a, geo::mul(w.d, along)), w.n))
                }
                f => {
                    if let Some(a) = w.face_arc(f) {
                        return Some(Geo::Arc(a));
                    }
                    Some(Geo::Line(w.face_point(f), w.d))
                }
            }
        }
        "door" | "window" => {
            let (p, d, w) = geo::opening_place(cx, e)?;
            let width = geo::opening_width(pr, e).unwrap_or(0.0);
            let at = match face {
                "start" => geo::sub(p, geo::mul(d, width / 2.0)),
                "end" => geo::add(p, geo::mul(d, width / 2.0)),
                _ => p,
            };
            let n = geo::left(d);
            if let Some(pt) = point {
                let off = if pt == "end" { w.right } else { w.left };
                return Some(Geo::Point(geo::add(at, geo::mul(n, off))));
            }
            Some(Geo::Line(at, n))
        }
        "grid" => {
            let a = geo::pt(e.get("start"))?;
            let b = geo::pt(e.get("end"))?;
            if let Some(pt) = point {
                return Some(Geo::Point(if pt == "end" { b } else { a }));
            }
            Some(Geo::Line(a, geo::unit(geo::sub(b, a))))
        }
        "line" => line_geo(e, point),
        "column" | "structuralcolumn" => {
            let at = geo::pt(e.get("at"))?;
            let (_, def) = common::element_type(pr, e)?;
            let w = common::num(def, "width").unwrap_or(0.0);
            Some(Geo::Circle(at, w / 2.0))
        }
        _ => None,
    }
}

/// A detail line's geometry: a straight one's line, an arc, a circle; with `point`, an end.
fn line_geo(e: &Value, point: Option<&str>) -> Option<Geo> {
    if let Some(c) = geo::pt(e.get("centre")) {
        if let Some(r) = common::num(e, "radius") {
            if let Some(pt) = point {
                let _ = pt;
                return Some(Geo::Point([c[0] + r, c[1]]));
            }
            return Some(Geo::Circle(c, r));
        }
    }
    let (a, b) = match (geo::pt(e.get("start")), geo::pt(e.get("end"))) {
        (Some(a), Some(b)) => (a, b),
        _ => {
            let pts = common::points(e.get("points").unwrap_or(&Value::Null));
            if pts.len() >= 2 {
                if let Some(pt) = point {
                    return Some(Geo::Point(if pt == "end" { *pts.last()? } else { pts[0] }));
                }
                return Some(Geo::Line(pts[0], geo::unit(geo::sub(pts[1], pts[0]))));
            }
            for k in ["control", "fit"] {
                let pts = common::points(e.get(k).unwrap_or(&Value::Null));
                if pts.len() >= 2 {
                    if let Some(pt) = point {
                        return Some(Geo::Point(if pt == "end" { *pts.last()? } else { pts[0] }));
                    }
                }
            }
            return None;
        }
    };
    if let Some(pt) = point {
        return Some(Geo::Point(if pt == "end" { b } else { a }));
    }
    if let Some(t) = common::num(e, "arc").filter(|t| *t != 0.0) {
        return Arc::from_chord(a, b, t).map(Geo::Arc);
    }
    Some(Geo::Line(a, geo::unit(geo::sub(b, a))))
}

/// The way a dimension counts its segments: west to east, or south to north.
fn canonical(u: P) -> P {
    if u[0] < -1e-9 || (u[0].abs() <= 1e-9 && u[1] < 0.0) {
        [-u[0], -u[1]]
    } else {
        u
    }
}

fn geo_point(g: &Geo) -> P {
    match g {
        Geo::Line(p, _) | Geo::Point(p) | Geo::Circle(p, _) => *p,
        Geo::Arc(a) => a.c,
    }
}

/// The lengths between references along a direction: their places sorted, and the steps between.
fn along(geos: &[Geo], u: P) -> Vec<f64> {
    let mut at: Vec<f64> = geos.iter().map(|g| geo::dot(geo_point(g), u)).collect();
    at.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    at.windows(2).map(|w| w[1] - w[0]).collect()
}

/// An aligned dimension's lengths: square to its lines, or along its first two points.
fn aligned(geos: &[Geo]) -> Vec<f64> {
    let line = geos.iter().find_map(|g| if let Geo::Line(_, d) = g { Some(*d) } else { None });
    let u = match line {
        Some(d) => geo::left(d),
        None => {
            let pts: Vec<P> = geos.iter().map(geo_point).collect();
            if pts.len() < 2 {
                return Vec::new();
            }
            geo::unit(geo::sub(pts[1], pts[0]))
        }
    };
    along(geos, canonical(u))
}

/// The angle between two lines that meet, on the side of `at`.
fn angular(geos: &[Geo], at: P) -> Option<f64> {
    let (p, d) = match geos.first()? {
        Geo::Line(p, d) => (*p, *d),
        _ => return None,
    };
    let (q, e) = match geos.get(1)? {
        Geo::Line(q, e) => (*q, *e),
        _ => return None,
    };
    let o = geo::meet(p, d, q, e)?;
    let v = geo::sub(at, o);
    // at = s d + t e: the rays toward `at`
    let den = geo::cross(d, e);
    let s = geo::cross(v, e) / den;
    let t = geo::cross(d, v) / den;
    let d1 = if s < 0.0 { geo::mul(d, -1.0) } else { d };
    let e1 = if t < 0.0 { geo::mul(e, -1.0) } else { e };
    let c = geo::dot(geo::unit(d1), geo::unit(e1)).clamp(-1.0, 1.0);
    Some(c.acos().to_degrees())
}

/// What a dimension measures, unrounded, in mm (degrees for an angle).
pub fn measure(cx: &Ctx, x: &Value) -> Vec<f64> {
    let refs: Vec<Geo> = match x.get("refs").and_then(|r| r.as_arr()) {
        Some(a) => a.iter().filter_map(|r| resolve(cx, r)).collect(),
        None => Vec::new(),
    };
    let kind = common::text(x, "kind").unwrap_or("aligned");
    let at = geo::pt(x.get("at")).unwrap_or([0.0, 0.0]);
    match kind {
        "linear" => {
            let u = if common::text(x, "orient") == Some("vertical") { [0.0, 1.0] } else { [1.0, 0.0] };
            along(&refs, u)
        }
        "angular" => angular(&refs, at).into_iter().collect(),
        "radial" | "diameter" => {
            let r = match refs.first() {
                Some(Geo::Circle(_, r)) => Some(*r),
                Some(Geo::Arc(a)) => Some(a.r),
                _ => None,
            };
            r.map(|r| if kind == "diameter" { 2.0 * r } else { r }).into_iter().collect()
        }
        "arc_length" => {
            let a = match refs.first() {
                Some(Geo::Arc(a)) => *a,
                Some(Geo::Circle(c, r)) => Arc { c: *c, r: *r, a0: 0.0, sweep: 2.0 * std::f64::consts::PI },
                _ => return Vec::new(),
            };
            if let (Some(Geo::Point(p)), Some(Geo::Point(q))) = (refs.get(1), refs.get(2)) {
                let ang = |p: P| (p[1] - a.c[1]).atan2(p[0] - a.c[0]);
                let norm = |x: f64| {
                    let mut f = (x - a.a0) / a.sweep;
                    let tau = 2.0 * std::f64::consts::PI / a.sweep.abs();
                    while f < 0.0 {
                        f += tau;
                    }
                    f
                };
                let (f1, f2) = (norm(ang(*p)), norm(ang(*q)));
                return vec![(f2 - f1).abs() * a.length()];
            }
            vec![a.length()]
        }
        _ => aligned(&refs),
    }
}

/// The dimension type a dimension letters in: its name and definition.
fn dim_type<'p>(cx: &'p Ctx, x: &Value) -> Option<(String, Option<&'p Value>)> {
    let g = common::text(x, "type")?;
    let name = common::lib_name_of(cx.pr, "dimension-type", g)?;
    let def = cx.pr.section("dimension_types").and_then(|m| m.get(&name));
    Some((name, def))
}

pub fn view(cx: &Ctx, x: &mut Value) {
    let kind = common::text(x, "kind").unwrap_or("aligned").to_string();
    let (tname, tdef) = match dim_type(cx, x) {
        Some((n, d)) => (Some(n), d.cloned()),
        None => (None, None),
    };
    let raw = measure(cx, x);
    let tget = |k: &str| tdef.as_ref().and_then(|d| d.get(k)).cloned();
    let units = tget("units").and_then(|v| v.as_str().map(|s| s.to_string())).unwrap_or_else(|| units::project_units(cx.pr));
    let decimals = tget("decimals").and_then(|v| v.as_u64());
    let eq_text = tget("equality_text").and_then(|v| v.as_str().map(|s| s.to_string())).unwrap_or_else(|| "EQ".into());
    let rsym = tget("radius_symbol").and_then(|v| v.as_str().map(|s| s.to_string())).unwrap_or_else(|| "R".into());
    let dsym = tget("diameter_symbol").and_then(|v| v.as_str().map(|s| s.to_string())).unwrap_or_else(|| "Ø".into());
    let equality = x.get("equality").and_then(|v| v.as_bool()).unwrap_or(false);
    let texts: Vec<Value> = x.get("texts").and_then(|t| t.as_arr()).cloned().unwrap_or_default();
    let mut labels = Vec::new();
    for (i, v) in raw.iter().enumerate() {
        let number = match kind.as_str() {
            "angular" => format!("{}°", units::shortest(r2(*v))),
            "radial" => format!("{} {}", rsym, units::length_text(*v, &units, decimals)),
            "diameter" => format!("{} {}", dsym, units::length_text(*v, &units, decimals)),
            _ => units::length_text(*v, &units, decimals),
        };
        let seg = texts.iter().find(|t| t.get("segment").and_then(|s| s.as_u64()) == Some(i as u64));
        let field = |k: &str| -> Option<String> {
            if let Some(s) = seg.and_then(|s| s.get(k)).and_then(|v| v.as_str()) {
                if !s.is_empty() {
                    return Some(s.to_string());
                }
            }
            x.get(k).and_then(|v| v.as_str()).filter(|s| !s.is_empty()).map(|s| s.to_string())
        };
        let label = if let Some(r) = field("replace") {
            r
        } else if equality && raw.len() > 1 {
            eq_text.clone()
        } else {
            format!("{}{}{}", field("prefix").unwrap_or_default(), number, field("suffix").unwrap_or_default())
        };
        labels.push(Value::Str(label));
    }
    if let Some(n) = tname {
        x.set("type", Value::Str(n));
    }
    x.set("values", Value::Arr(raw.iter().map(|v| Value::f(r2(*v))).collect()));
    x.set("labels", Value::Arr(labels));
}

