//! Tags, text notes and spot elevations as `elements` shows them: where a tag stands and what it
//! says, a note's type and size, the height a spot reads, and the level of the plan each is in.

use super::geo::{self, P};
use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, r2, Ctx};

/// The level a view (by GUID) is the plan of: a level's own plan, or a plan view's level; null
/// for a section, an elevation, a sheet or a 3D view.
pub fn view_level(pr: &Project, g: Option<&str>) -> Value {
    let Some(g) = g else { return Value::Null };
    match common::by_guid(pr, g) {
        Some((_, e)) => match common::category(e) {
            "level" => Value::s(g),
            "planview" => e.get("level").cloned().unwrap_or(Value::Null),
            _ => Value::Null,
        },
        None => Value::Null,
    }
}

/// The point of an element a tag names it at: a door's or window's place on its wall, a room's
/// point, the middle of a wall or a run, a column's or a component's point, the middle of a
/// floor's, ceiling's or roof's outline (its corners' mean), a stair's or ramp's start.
pub fn host_point(cx: &Ctx, e: &Value) -> Option<P> {
    match common::category(e) {
        "door" | "window" => geo::opening_place(cx, e).map(|(p, _, _)| p),
        "room" => geo::pt(e.get("point")),
        "wall" => {
            let a = geo::pt(e.get("start"))?;
            let b = geo::pt(e.get("end"))?;
            if let Some(t) = common::num(e, "arc").filter(|t| *t != 0.0) {
                if let Some(arc) = geo::Arc::from_chord(a, b, t) {
                    return Some(arc.at(0.5));
                }
            }
            Some(geo::lerp(a, b, 0.5))
        }
        "floor" | "ceiling" | "roof" | "shaft" | "mass" => {
            let pts = common::points(e.get("boundary").unwrap_or(&Value::Null));
            if pts.is_empty() {
                return None;
            }
            let n = pts.len() as f64;
            let sx: f64 = pts.iter().map(|p| p[0]).sum();
            let sy: f64 = pts.iter().map(|p| p[1]).sum();
            Some([sx / n, sy / n])
        }
        "stair" | "ramp" => geo::pt(e.get("start")),
        _ => {
            if let Some(p) = geo::pt(e.get("at")) {
                return Some(p);
            }
            let a = geo::pt(e.get("start"))?;
            let b = geo::pt(e.get("end"))?;
            Some(geo::lerp(a, b, 0.5))
        }
    }
}

/// The level an element stands on (a door's or window's wall's).
pub fn host_level(pr: &Project, e: &Value) -> Value {
    match common::category(e) {
        "door" | "window" => common::target(pr, e, "host")
            .and_then(|(_, w)| w.get("level").cloned())
            .unwrap_or(Value::Null),
        _ => e.get("level").cloned().unwrap_or(Value::Null),
    }
}

/// A type's name as the element names it (a family's type by its own name).
pub fn type_name(pr: &Project, e: &Value) -> Option<String> {
    let g = common::text(e, "type")?;
    if let Some(fg) = common::text(e, "family") {
        if let Some((fname, _)) = common::family(pr, fg) {
            if let Some(t) = common::family_type(pr, &fname, g) {
                return Some(t);
            }
        }
    }
    pr.lib_name(g).map(|n| match n.split_once(": ") {
        Some((_, t)) if pr.lib_find_guid(g).and_then(|l| pr.library.get(&l)).and_then(|l| l.get("kind")).and_then(|k| k.as_str()) == Some("family-type") => t.to_string(),
        _ => n,
    })
}

/// What a tag says of an element without a label: a door's or window's mark, a room's name, else
/// its type's name ("?" for none).
pub fn tag_text(pr: &Project, e: &Value) -> String {
    let s = match common::category(e) {
        "door" | "window" => common::text(e, "mark").map(|s| s.to_string()),
        "room" => common::text(e, "name").map(|s| s.to_string()),
        _ => type_name(pr, e),
    };
    match s {
        Some(s) if !s.is_empty() => s,
        _ => "?".into(),
    }
}

pub fn tag_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    let Some((hid, h)) = common::target(pr, x, "host") else { return };
    let off = geo::pt(x.get("offset")).unwrap_or([0.0, 0.0]);
    if let Some(p) = host_point(cx, h) {
        x.set("at", geo::pval(geo::add(p, off)));
    }
    x.set("level", host_level(pr, h));
    let text = match common::text(x, "label") {
        Some(label) => match crate::readers::schedule::field_display(cx, hid, label) {
            Some(s) if !s.is_empty() => s,
            Some(_) => "?".into(),
            None => tag_text(pr, h),
        },
        None => tag_text(pr, h),
    };
    x.set("text", Value::Str(text));
}

pub fn text_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    if let Some(g) = common::text(x, "type").map(|s| s.to_string()) {
        if let Some(name) = common::lib_name_of(pr, "text-type", &g) {
            let size = pr
                .section("text_types")
                .and_then(|m| m.get(&name))
                .and_then(|t| common::num(t, "size"))
                .unwrap_or(2.5);
            x.set("type", Value::Str(name));
            x.set("size", Value::f(size));
        }
    }
    let lv = view_level(pr, common::text(x, "view"));
    x.set("level", lv);
}

pub fn spot_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    let lv = view_level(pr, common::text(x, "view"));
    let at = geo::pt(x.get("at")).unwrap_or([0.0, 0.0]);
    let elev = match common::target(pr, x, "host") {
        Some((hid, h)) => super::heights::top_at(cx, hid, h, at),
        None => {
            if lv.is_null() {
                Some(at[1])
            } else {
                None
            }
        }
    };
    if let Some(z) = elev {
        x.set("elevation", Value::f(r2(z)));
    }
    x.set("level", lv);
}

//! The height of the top of what a spot elevation stands on, at its point: a floor's top (sloped
//! or not), a roof's top along its slopes, a wall's or a column's top, a run's top along it, a
//! component's top.

use super::geo::{self, P};
use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, Ctx};

fn level_elev(pr: &Project, e: &Value) -> f64 {
    common::text(e, "level").and_then(|g| common::level_elev(pr, g)).unwrap_or(0.0)
}

/// How far `p` lies inside the edge from `a` to `b` of an outline (square to it).
fn edge_dist(p: P, a: P, b: P) -> f64 {
    let d = geo::unit(geo::sub(b, a));
    geo::cross(d, geo::sub(p, a)).abs()
}

fn type_def<'p>(pr: &'p Project, e: &Value) -> Option<&'p Value> {
    common::element_type(pr, e).map(|(_, d)| d)
}

/// A family's parameter for a component: its own value, its type's, its family's.
pub fn family_param(pr: &Project, e: &Value, name: &str) -> Option<f64> {
    if let Some(v) = e.get("params").and_then(|p| p.get(name)).and_then(|v| v.as_f64()) {
        return Some(v);
    }
    let fg = common::text(e, "family")?;
    let (fname, fam) = common::family(pr, fg)?;
    if let Some(tn) = common::text(e, "type").and_then(|g| common::family_type(pr, &fname, g)) {
        if let Some(v) = fam.get("types").and_then(|t| t.get(&tn)).and_then(|t| t.get(name)).and_then(|v| v.as_f64()) {
            return Some(v);
        }
    }
    for p in fam.get("parameters")?.as_arr()? {
        if common::text(p, "name") == Some(name) {
            return common::num(p, "value");
        }
    }
    None
}

/// The top of a roof at `p`: its planes rising from its edges (less the overhang) at their slopes,
/// the lowest of them there, and its thickness over that.
fn roof_top(pr: &Project, e: &Value, p: P) -> Option<f64> {
    let base = level_elev(pr, e) + common::num(e, "offset").unwrap_or(0.0);
    let t = type_def(pr, e).and_then(|d| common::num(d, "thickness")).unwrap_or(0.0);
    let slope = common::num(e, "slope").unwrap_or(0.0);
    let pts = common::points(e.get("boundary").unwrap_or(&Value::Null));
    let over = common::num(e, "overhang").unwrap_or(0.0);
    let gables: Vec<usize> = e
        .get("gables")
        .and_then(|g| g.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_u64()).map(|x| x as usize).collect())
        .unwrap_or_default();
    let slopes: Vec<f64> = e
        .get("slopes")
        .and_then(|g| g.as_arr())
        .map(|a| a.iter().map(|x| x.as_f64().unwrap_or(0.0)).collect())
        .unwrap_or_default();
    let n = pts.len();
    let mut best: Option<(f64, f64)> = None;
    for i in 0..n {
        if gables.contains(&i) {
            continue;
        }
        let s = match slopes.get(i) {
            Some(x) if *x != 0.0 => *x,
            _ => slope,
        };
        if s <= 0.0 {
            continue;
        }
        let (a, b) = (pts[i], pts[(i + 1) % n]);
        let h = (edge_dist(p, a, b) - over) * s.to_radians().tan();
        if best.map(|(bh, _)| h < bh).unwrap_or(true) {
            best = Some((h, s));
        }
    }
    match best {
        Some((h, s)) => Some(base + h + t / s.to_radians().cos()),
        None => Some(base + t),
    }
}

/// The top of a floor at `p`: its level and offset, risen along its arrow at its slope.
fn floor_top(pr: &Project, e: &Value, p: P) -> f64 {
    let mut z = level_elev(pr, e) + common::num(e, "offset").unwrap_or(0.0);
    if let (Some(s), Some(arrow)) = (common::num(e, "slope"), e.get("arrow")) {
        let pts = common::points(arrow);
        if pts.len() == 2 && s != 0.0 {
            let d = geo::unit(geo::sub(pts[1], pts[0]));
            z += geo::dot(geo::sub(p, pts[0]), d) * s.to_radians().tan();
        }
    }
    z
}

/// The top of a run (pipe, duct, beam…) at `p`: its line's height there and its size over it.
fn run_top(pr: &Project, e: &Value, p: P) -> Option<f64> {
    let a = geo::pt(e.get("start"))?;
    let b = geo::pt(e.get("end"))?;
    let o1 = common::num(e, "offset").unwrap_or(0.0);
    let o2 = common::num(e, "end_offset").unwrap_or(o1);
    let l = geo::dist(a, b);
    let f = if l > 0.0 { (geo::dot(geo::sub(p, a), geo::sub(b, a)) / (l * l)).clamp(0.0, 1.0) } else { 0.0 };
    let z = level_elev(pr, e) + o1 + (o2 - o1) * f;
    let depth = type_def(pr, e).and_then(|d| common::num(d, "depth")).unwrap_or(0.0);
    let just = common::text(e, "justify").unwrap_or(if common::category(e) == "beam" { "top" } else { "centre" });
    Some(match just {
        "top" => z,
        "bottom" => z + depth,
        _ => z + depth / 2.0,
    })
}

/// The height of the top of `h` (the spot's host) at `p`.
pub fn top_at(cx: &Ctx, _hid: u64, h: &Value, p: P) -> Option<f64> {
    let pr = cx.pr;
    match common::category(h) {
        "floor" => Some(floor_top(pr, h, p)),
        "roof" => roof_top(pr, h, p),
        "wall" | "column" | "structuralcolumn" => {
            Some(level_elev(pr, h) + common::num(h, "base_offset").unwrap_or(0.0) + common::num(h, "height").unwrap_or(0.0))
        }
        "footing" => Some(level_elev(pr, h) + common::num(h, "offset").unwrap_or(0.0)),
        "component" => Some(level_elev(pr, h) + common::num(h, "offset").unwrap_or(0.0) + family_param(pr, h, "Height").unwrap_or(0.0)),
        "beam" | "pipe" | "duct" | "conduit" | "cabletray" | "wire" | "downconductor" | "groundconductor" | "cable" | "stripfooting" => run_top(pr, h, p),
        "ceiling" => Some(level_elev(pr, h) + common::num(h, "offset").unwrap_or(2600.0)),
        "stair" | "ramp" => {
            let top = common::text(h, "top_level").and_then(|g| common::level_elev(pr, g));
            Some(top.unwrap_or_else(|| level_elev(pr, h) + common::num(h, "height").unwrap_or(0.0)))
        }
        _ => None,
    }
}

//! Sections, elevations, sheets and viewports as `elements` shows them: a section's length and the
//! way it looks, a sheet's paper and the viewports on it, a viewport's title and its size on the
//! paper.

use super::geo;
use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, Ctx};

/// A section's or an elevation's length and the way it looks (to the left of its line).
pub fn section_view(x: &mut Value) {
    let (Some(a), Some(b)) = (geo::pt(x.get("start")), geo::pt(x.get("end"))) else { return };
    let d = geo::sub(b, a);
    let l = geo::len(d);
    x.set("length", Value::f(l));
    if l > 0.0 {
        let nz = |v: f64| if v == 0.0 { 0.0 } else { v };
        x.set("looking", Value::Arr(vec![Value::f(nz(-d[1] / l)), Value::f(nz(d[0] / l))]));
    }
}

/// A sheet size's paper, landscape, mm.
pub fn paper(size: &str) -> Option<[f64; 2]> {
    Some(match size.trim().to_uppercase().as_str() {
        "A0" => [1189.0, 841.0],
        "A1" => [841.0, 594.0],
        "A2" => [594.0, 420.0],
        "A3" => [420.0, 297.0],
        "A4" => [297.0, 210.0],
        "ANSI A" | "LETTER" => [279.4, 215.9],
        "ANSI B" | "TABLOID" | "LEDGER" => [431.8, 279.4],
        "ANSI C" => [558.8, 431.8],
        "ANSI D" => [863.6, 558.8],
        "ANSI E" => [1117.6, 863.6],
        "ARCH A" => [304.8, 228.6],
        "ARCH B" => [457.2, 304.8],
        "ARCH C" => [609.6, 457.2],
        "ARCH D" => [914.4, 609.6],
        "ARCH E" => [1219.2, 914.4],
        "ARCH E1" => [1066.8, 762.0],
        _ => return None,
    })
}

pub fn sheet_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    let size = common::text(x, "size").unwrap_or("A3").to_string();
    if let Some(p) = paper(&size) {
        x.set("paper", geo::pval(p));
    }
    let g = common::text(x, "guid").unwrap_or("").to_string();
    let vps: Vec<Value> = pr
        .elements
        .iter()
        .filter(|(_, e)| common::category(e) == "viewport" && common::text(e, "sheet") == Some(g.as_str()))
        .map(|(id, _)| Value::u(*id))
        .collect();
    x.set("viewports", Value::Arr(vps));
}

pub fn viewport_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    let Some((vid, v)) = common::target(pr, x, "view") else { return };
    if let Some(n) = common::text(v, "name") {
        x.set("title", Value::s(n));
    }
    let scale = common::num(x, "scale").unwrap_or(100.0);
    if let Some(s) = super::extent::viewport_size(cx, vid, v, scale, x) {
        x.set("size", geo::pval(s));
    }
}

/// The level of a plan view (a level's own, or a plan view's).
pub fn plan_level(pr: &Project, id: u64) -> Option<u64> {
    crate::model::level_of_view(pr, id)
}

//! Detail lines, filled regions, detail groups and repeating details as `elements` shows them: a
//! line's shape, length and style, a region's area and type, a group's type and members, how many
//! times a detail repeats.

use super::annot::view_level;
use super::geo::{self, Arc, P};
use crate::json::Value;
use crate::readers::common::{self, r2, Ctx};
use std::f64::consts::PI;

/// What kind of curve a detail line is.
pub fn shape(e: &Value) -> &'static str {
    if e.get("control").is_some() {
        return "spline";
    }
    if e.get("fit").is_some() {
        return "fitted spline";
    }
    if e.get("radii").is_some() {
        return if e.get("span").map(|s| !s.is_null()).unwrap_or(false) { "partial ellipse" } else { "ellipse" };
    }
    if e.get("radius").is_some() {
        return "circle";
    }
    if e.get("points").is_some() {
        return "polyline";
    }
    if common::num(e, "arc").map(|a| a != 0.0).unwrap_or(false) {
        return "arc";
    }
    "line"
}

/// A straight segment's or an arc's length, from `a` to `b` turning `turn` degrees.
fn seg_len(a: P, b: P, turn: f64) -> f64 {
    match Arc::from_chord(a, b, turn) {
        Some(arc) if turn != 0.0 => arc.length(),
        _ => geo::dist(a, b),
    }
}

/// An ellipse's points (or part of one), as the original draws it.
pub fn ellipse_points(c: P, rx: f64, ry: f64, angle: f64, span: Option<(f64, f64)>) -> Vec<P> {
    let (from, to) = match span {
        Some((a, b)) => (a.to_radians(), b.to_radians()),
        None => (0.0, 2.0 * PI),
    };
    let n = ((to - from).abs() / (2.0 * PI) * 200.0).ceil().max(1.0) as usize;
    let (s, co) = angle.to_radians().sin_cos();
    (0..=n)
        .map(|i| {
            let t = from + (to - from) * i as f64 / n as f64;
            let (x, y) = (rx * t.cos(), ry * t.sin());
            [c[0] + x * co - y * s, c[1] + x * s + y * co]
        })
        .collect()
}

fn poly_len(pts: &[P]) -> f64 {
    pts.windows(2).map(|w| geo::dist(w[0], w[1])).sum()
}

/// A clamped B-spline's points (degree from its knots, else 3), as the original draws it.
pub fn spline_points(ctrl: &[P], knots: Option<Vec<f64>>) -> Vec<P> {
    let n = ctrl.len();
    if n < 2 {
        return ctrl.to_vec();
    }
    let (deg, ks) = match knots {
        Some(k) if k.len() > n => (k.len() - n - 1, k),
        _ => {
            let d = 3.min(n - 1);
            let mut k = vec![0.0; d + 1];
            let inner = n - d - 1;
            for i in 1..=inner {
                k.push(i as f64 / (inner + 1) as f64);
            }
            k.extend(std::iter::repeat(1.0).take(d + 1));
            (d, k)
        }
    };
    let (t0, t1) = (ks[deg], ks[n]);
    let steps = 64 * (n - deg).max(1);
    (0..=steps)
        .map(|i| {
            let t = t0 + (t1 - t0) * i as f64 / steps as f64;
            de_boor(ctrl, &ks, deg, t)
        })
        .collect()
}

fn de_boor(ctrl: &[P], ks: &[f64], deg: usize, t: f64) -> P {
    let n = ctrl.len();
    let mut k = deg;
    while k + 1 < n && t >= ks[k + 1] {
        k += 1;
    }
    let mut d: Vec<P> = (0..=deg).map(|j| ctrl[j + k - deg]).collect();
    for r in 1..=deg {
        for j in (r..=deg).rev() {
            let i = j + k - deg;
            let den = ks[i + deg - r + 1] - ks[i];
            let a = if den == 0.0 { 0.0 } else { (t - ks[i]) / den };
            d[j] = geo::lerp(d[j - 1], d[j], a);
        }
    }
    d[deg]
}

/// A spline through points (a natural cubic through them, by chord length).
pub fn fit_points(pts: &[P], _t0: Option<P>, _t1: Option<P>) -> Vec<P> {
    let n = pts.len();
    if n < 3 {
        return pts.to_vec();
    }
    // chord-length parameters
    let mut u = vec![0.0];
    for i in 1..n {
        u.push(u[i - 1] + geo::dist(pts[i - 1], pts[i]));
    }
    let mut out = Vec::new();
    for dim in 0..2 {
        let y: Vec<f64> = pts.iter().map(|p| p[dim]).collect();
        let m = natural_second(&u, &y);
        out.push((u.clone(), y, m));
    }
    let steps = 64;
    let mut res = Vec::new();
    for i in 0..n - 1 {
        for s in 0..steps {
            let t = u[i] + (u[i + 1] - u[i]) * s as f64 / steps as f64;
            res.push([cubic_at(&out[0], i, t), cubic_at(&out[1], i, t)]);
        }
    }
    res.push(pts[n - 1]);
    res
}

fn natural_second(x: &[f64], y: &[f64]) -> Vec<f64> {
    let n = x.len();
    let mut m = vec![0.0; n];
    if n < 3 {
        return m;
    }
    let mut a = vec![0.0; n];
    let mut b = vec![0.0; n];
    let mut c = vec![0.0; n];
    let mut d = vec![0.0; n];
    b[0] = 1.0;
    b[n - 1] = 1.0;
    for i in 1..n - 1 {
        let h0 = x[i] - x[i - 1];
        let h1 = x[i + 1] - x[i];
        a[i] = h0;
        b[i] = 2.0 * (h0 + h1);
        c[i] = h1;
        d[i] = 6.0 * ((y[i + 1] - y[i]) / h1 - (y[i] - y[i - 1]) / h0);
    }
    for i in 1..n {
        let w = a[i] / b[i - 1];
        b[i] -= w * c[i - 1];
        d[i] -= w * d[i - 1];
    }
    m[n - 1] = d[n - 1] / b[n - 1];
    for i in (0..n - 1).rev() {
        m[i] = (d[i] - c[i] * m[i + 1]) / b[i];
    }
    m
}

fn cubic_at(s: &(Vec<f64>, Vec<f64>, Vec<f64>), i: usize, t: f64) -> f64 {
    let (x, y, m) = s;
    let h = x[i + 1] - x[i];
    let a = (x[i + 1] - t) / h;
    let b = (t - x[i]) / h;
    a * y[i] + b * y[i + 1] + ((a * a * a - a) * m[i] + (b * b * b - b) * m[i + 1]) * h * h / 6.0
}

/// How long a detail line is along its curve.
pub fn line_length(e: &Value) -> Option<f64> {
    match shape(e) {
        "line" | "arc" => {
            let a = geo::pt(e.get("start"))?;
            let b = geo::pt(e.get("end"))?;
            Some(seg_len(a, b, common::num(e, "arc").unwrap_or(0.0)))
        }
        "polyline" => {
            let pts = common::points(e.get("points")?);
            let turns: Vec<f64> = e
                .get("arcs")
                .and_then(|a| a.as_arr())
                .map(|a| a.iter().map(|x| x.as_f64().unwrap_or(0.0)).collect())
                .unwrap_or_default();
            let closed = e.get("closed").and_then(|c| c.as_bool()).unwrap_or(false);
            let n = if closed { pts.len() } else { pts.len().saturating_sub(1) };
            let mut l = 0.0;
            for i in 0..n {
                l += seg_len(pts[i], pts[(i + 1) % pts.len()], turns.get(i).cloned().unwrap_or(0.0));
            }
            Some(l)
        }
        "circle" => Some(2.0 * PI * common::num(e, "radius")?.abs()),
        "ellipse" | "partial ellipse" => {
            let c = geo::pt(e.get("centre"))?;
            let rr = common::points(&Value::Arr(vec![e.get("radii")?.clone()]));
            let (rx, ry) = (rr.first()?[0].abs(), rr.first()?[1].abs());
            let span = geo::pt(e.get("span")).map(|s| (s[0], s[1]));
            Some(poly_len(&ellipse_points(c, rx, ry, common::num(e, "angle").unwrap_or(0.0), span)))
        }
        "spline" => {
            let ctrl = common::points(e.get("control")?);
            let knots = e.get("knots").and_then(|k| k.as_arr()).map(|a| a.iter().filter_map(|x| x.as_f64()).collect());
            Some(poly_len(&spline_points(&ctrl, knots)))
        }
        "fitted spline" => {
            let pts = common::points(e.get("fit")?);
            Some(poly_len(&fit_points(&pts, geo::pt(e.get("start_tangent")), geo::pt(e.get("end_tangent")))))
        }
        _ => None,
    }
}

pub fn line_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    let sh = shape(x);
    if let Some(l) = line_length(x) {
        x.set("length", Value::f(r2(l)));
    }
    x.set("shape", Value::s(sh));
    if let Some(g) = common::text(x, "style").map(|s| s.to_string()) {
        if let Some(n) = common::lib_name_of(pr, "line-style", &g) {
            x.set("style", Value::Str(n));
        }
    }
    let lv = view_level(pr, common::text(x, "view"));
    x.set("level", lv);
}

/// The signed area of a loop of a region's sketch lines.
fn loops_area(sketch: &[Value]) -> f64 {
    // the lines, each from its start to its end (an arc by its `arc` turn), chained into loops
    let mut segs: Vec<(P, P, f64)> = Vec::new();
    for s in sketch {
        if let (Some(a), Some(b)) = (geo::pt(s.get("start")), geo::pt(s.get("end"))) {
            segs.push((a, b, common::num(s, "arc").unwrap_or(0.0)));
        } else if let (Some(c), Some(r)) = (geo::pt(s.get("centre")), common::num(s, "radius")) {
            // a whole circle: a loop of its own
            let _ = c;
            segs.push(([0.0, 0.0], [0.0, 0.0], f64::NAN));
            let _ = r;
        }
    }
    let mut used = vec![false; segs.len()];
    let mut areas = Vec::new();
    for i in 0..segs.len() {
        if used[i] {
            continue;
        }
        if segs[i].2.is_nan() {
            used[i] = true;
            if let Some(s) = sketch.get(i) {
                let r = common::num(s, "radius").unwrap_or(0.0);
                areas.push(PI * r * r);
            }
            continue;
        }
        used[i] = true;
        let mut lp: Vec<(P, P, f64)> = vec![segs[i]];
        let start = segs[i].0;
        let mut cur = segs[i].1;
        let mut guard = 0;
        while geo::dist(cur, start) > 1e-6 && guard < segs.len() + 1 {
            guard += 1;
            let mut found = false;
            for j in 0..segs.len() {
                if used[j] || segs[j].2.is_nan() {
                    continue;
                }
                if geo::dist(segs[j].0, cur) <= 1e-6 {
                    used[j] = true;
                    lp.push(segs[j]);
                    cur = segs[j].1;
                    found = true;
                    break;
                }
                if geo::dist(segs[j].1, cur) <= 1e-6 {
                    used[j] = true;
                    lp.push((segs[j].1, segs[j].0, -segs[j].2));
                    cur = segs[j].0;
                    found = true;
                    break;
                }
            }
            if !found {
                break;
            }
        }
        let mut a = 0.0;
        for (p, q, t) in &lp {
            a += geo::cross(*p, *q) / 2.0;
            if *t != 0.0 {
                if let Some(arc) = Arc::from_chord(*p, *q, *t) {
                    // the segment between the chord and the arc, on the side it bulges
                    let th = arc.sweep.abs();
                    let seg = arc.r * arc.r / 2.0 * (th - th.sin());
                    a += if arc.sweep > 0.0 { -seg } else { seg };
                }
            }
        }
        areas.push(a.abs());
    }
    // the largest loops are outlines; a loop inside one is a hole, one inside that an island:
    // without containment tests, the first is the outline and the rest holes
    if areas.is_empty() {
        return 0.0;
    }
    let mut sorted = areas.clone();
    sorted.sort_by(|a, b| b.partial_cmp(a).unwrap());
    let total = sorted[0] - sorted[1..].iter().sum::<f64>();
    total
}

pub fn region_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    if let Some(sk) = x.get("sketch").and_then(|s| s.as_arr()) {
        let a = loops_area(sk);
        x.set("area_m2", Value::f(r2(a / 1e6)));
    }
    if let Some(g) = common::text(x, "type").map(|s| s.to_string()) {
        if let Some(n) = common::lib_name_of(pr, "filled-region-type", &g) {
            x.set("type", Value::Str(n));
        }
    }
    if let Some(g) = common::text(x, "line_style").map(|s| s.to_string()) {
        if let Some(n) = common::lib_name_of(pr, "line-style", &g) {
            x.set("line_style", Value::Str(n));
        }
    }
    if x.get("pattern_angle").is_none() {
        x.set("pattern_angle", Value::f(0.0));
    }
    if x.get("pattern_origin").is_none() {
        x.set("pattern_origin", geo::pval([0.0, 0.0]));
    }
    let lv = view_level(pr, common::text(x, "view"));
    x.set("level", lv);
}

/// A detail group type's name and how many members it has, by its GUID.
fn group_type(cx: &Ctx, g: &str) -> Option<(String, usize)> {
    let name = common::lib_name_of(cx.pr, "detail-group", g)?;
    let n = cx
        .pr
        .section("detail_groups")
        .and_then(|m| m.get(&name))
        .and_then(|t| t.get("members"))
        .and_then(|m| m.as_arr())
        .map(|a| a.len())
        .unwrap_or(0);
    Some((name, n))
}

pub fn group_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    if let Some(g) = common::text(x, "type").map(|s| s.to_string()) {
        if let Some((n, m)) = group_type(cx, &g) {
            x.set("type", Value::Str(n));
            x.set("members", Value::u(m as u64));
        }
    }
    let lv = view_level(pr, common::text(x, "view"));
    x.set("level", lv);
}

/// How many times a repeating detail places its group along its line.
pub fn repeat_count(x: &Value) -> u64 {
    let (Some(a), Some(b)) = (geo::pt(x.get("start")), geo::pt(x.get("end"))) else { return 0 };
    let s = common::num(x, "spacing").unwrap_or(0.0);
    if s <= 0.0 {
        return 1;
    }
    ((geo::dist(a, b) / s + 1e-9).floor() as u64 + 1).min(2000)
}

pub fn repeating_view(cx: &Ctx, x: &mut Value) {
    let pr = cx.pr;
    if let Some(g) = common::text(x, "type").map(|s| s.to_string()) {
        if let Some((n, _)) = group_type(cx, &g) {
            x.set("type", Value::Str(n));
        }
    }
    let c = repeat_count(x);
    x.set("count", Value::u(c));
    let lv = view_level(pr, common::text(x, "view"));
    x.set("level", lv);
}

//! `ids_of`, `select_by_id` and `measure`: what names an element (its id, GUID, IFC GlobalId,
//! category and name), the elements a list of names finds and the plan that shows them, and what
//! a ruler between two points reads.

use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, r2, rn, Ctx};
use crate::session::Session;

const B64: &[u8; 64] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_$";

/// A GUID (hyphenated hex) compressed into IFC's 22-character GlobalId.
pub fn ifc_global_id(guid: &str) -> Option<String> {
    let hex: String = guid.chars().filter(|c| *c != '-').collect();
    if hex.len() != 32 {
        return None;
    }
    let mut bytes = [0u8; 16];
    for i in 0..16 {
        bytes[i] = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).ok()?;
    }
    let mut out = String::with_capacity(22);
    // the first byte's top two bits… as IFC does: 2 bits, then 21 groups of 6 bits
    let v = u128::from_be_bytes(bytes);
    out.push(B64[((v >> 126) & 0x3) as usize] as char);
    for i in (0..21).rev() {
        out.push(B64[((v >> (6 * i)) & 0x3f) as usize] as char);
    }
    Some(out)
}

/// An IFC GlobalId back to its GUID (lowercase, hyphenated).
pub fn guid_of_global_id(s: &str) -> Option<String> {
    if s.len() != 22 {
        return None;
    }
    let mut v: u128 = 0;
    for (i, c) in s.bytes().enumerate() {
        let d = B64.iter().position(|b| *b == c)? as u128;
        if i == 0 {
            if d > 3 {
                return None;
            }
            v = d;
        } else {
            v = (v << 6) | d;
        }
    }
    let h = format!("{:032x}", v);
    Some(format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32]))
}

/// What a library entry or part is: its category (kind) and its name.
struct LibHit {
    id: u64,
    guid: String,
    category: String,
    name: String,
}

/// The parts of the library and of elements with ids and GUIDs of their own: types' layers,
/// families' forms, symbols and connectors, regions' sketch lines.
fn parts(pr: &Project) -> Vec<LibHit> {
    let mut out = Vec::new();
    for p in crate::media::library::parts(pr) {
        out.push(LibHit { id: p.id, guid: p.guid, category: p.kind.to_string(), name: format!("{} {} of {}", p.kind, p.index + 1, p.of) });
    }
    for (_, e) in &pr.elements {
        let Some(sk) = e.get("sketch").and_then(|s| s.as_arr()) else { continue };
        let cat = common::category(e);
        let g = common::text(e, "guid").unwrap_or("");
        for (i, s) in sk.iter().enumerate() {
            if let (Some(id), Some(sg)) = (s.get("id").and_then(|x| x.as_u64()), common::text(s, "guid")) {
                out.push(LibHit {
                    id,
                    guid: sg.to_string(),
                    category: "sketch line".into(),
                    name: format!("sketch line {} of {} {}", i + 1, cat, g),
                });
            }
        }
    }
    out
}

fn lib_category(kind: &str) -> String {
    match kind.strip_prefix("type:") {
        Some(c) => format!("{} type", c),
        None => kind.replace('-', " "),
    }
}

fn lib_hit(pr: &Project, id: u64) -> Option<LibHit> {
    if let Some(e) = pr.library.get(&id) {
        return Some(LibHit {
            id,
            guid: common::text(e, "guid").unwrap_or("").to_string(),
            category: lib_category(common::text(e, "kind").unwrap_or("")),
            name: common::text(e, "name").unwrap_or("").to_string(),
        });
    }
    parts(pr).into_iter().find(|p| p.id == id)
}

fn lib_hit_guid(pr: &Project, g: &str) -> Option<LibHit> {
    if let Some(id) = pr.lib_find_guid(g) {
        return lib_hit(pr, id);
    }
    parts(pr).into_iter().find(|p| p.guid == g)
}

/// What names an element: its name, else its type's, else its tag's text, number or mark.
pub fn element_name(cx: &Ctx, id: u64, e: &Value) -> String {
    let pr = cx.pr;
    if let Some(n) = common::text(e, "name") {
        return n.to_string();
    }
    if common::category(e) == "tag" {
        if let Some(v) = crate::readers::view::element_view(cx, id) {
            if let Some(t) = common::text(&v, "text") {
                return t.to_string();
            }
        }
    }
    if common::text(e, "type").is_some() {
        if let Some(t) = super::annot::type_name(pr, e) {
            return t;
        }
    }
    for k in ["number", "mark"] {
        if let Some(n) = common::text(e, k) {
            return n.to_string();
        }
    }
    String::new()
}

enum Found {
    Element(u64),
    Library(LibHit),
}

/// What a token names: an element or a library entry, by id, GUID (dashes and braces or not) or
/// IFC GlobalId.
fn find_token(pr: &Project, t: &str) -> Option<Found> {
    let t = t.trim();
    if t.is_empty() {
        return None;
    }
    if t.bytes().all(|b| b.is_ascii_digit()) {
        let id: u64 = t.parse().ok()?;
        if pr.elements.contains_key(&id) {
            return Some(Found::Element(id));
        }
        return lib_hit(pr, id).map(Found::Library);
    }
    let g = crate::model::normalize_guid(t).or_else(|| guid_of_global_id(t))?;
    if let Some(id) = pr.find_guid(&g) {
        return Some(Found::Element(id));
    }
    lib_hit_guid(pr, &g).map(Found::Library)
}

fn found_of_value(pr: &Project, v: &Value) -> Option<Found> {
    match v {
        Value::Num(crate::json::Num::U(u)) => find_token(pr, &u.to_string()),
        Value::Str(s) => find_token(pr, s),
        _ => None,
    }
}

/// `ids_of {ids}`.
pub fn cmd_ids_of(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let ids = match crate::commands::params::get(p, "ids") {
        Some(Value::Arr(a)) => a,
        _ => return Err("ids_of: `ids` [id or GUID, …] is required".into()),
    };
    let cx = Ctx::new(pr);
    let mut out = Vec::new();
    for v in ids {
        match found_of_value(pr, v) {
            Some(Found::Element(id)) => {
                let e = pr.el(id).unwrap();
                let g = common::text(e, "guid").unwrap_or("").to_string();
                out.push(jobj! {
                    "category" => common::category(e),
                    "guid" => g.clone(),
                    "id" => id,
                    "ifc" => ifc_global_id(&g).unwrap_or_default(),
                    "name" => element_name(&cx, id, e),
                });
            }
            Some(Found::Library(h)) => {
                out.push(jobj! {
                    "category" => h.category,
                    "guid" => h.guid.clone(),
                    "id" => h.id,
                    "ifc" => ifc_global_id(&h.guid).unwrap_or_default(),
                    "name" => h.name,
                });
            }
            None => return Err(format!("ids_of: no element or library entry {}", v.to_compact())),
        }
    }
    Ok(jobj! {"elements" => Value::Arr(out)})
}

/// `select_by_id {text}`.
pub fn cmd_select_by_id(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let text = match crate::commands::params::get(p, "text") {
        Some(Value::Str(t)) => t.clone(),
        _ => return Err("select_by_id: `text`, the ids, GUIDs or IFC GlobalIds to find, is required".into()),
    };
    let mut ids: Vec<u64> = Vec::new();
    let mut lib: Vec<u64> = Vec::new();
    let mut missing: Vec<Value> = Vec::new();
    for tok in text.split(|c: char| c.is_whitespace() || c == ',' || c == ';') {
        if tok.is_empty() {
            continue;
        }
        match find_token(pr, tok) {
            Some(Found::Element(id)) => {
                if !ids.contains(&id) {
                    ids.push(id);
                }
            }
            Some(Found::Library(h)) => {
                if !lib.contains(&h.id) {
                    lib.push(h.id);
                }
            }
            None => {
                let v = Value::s(tok);
                if !missing.contains(&v) {
                    missing.push(v);
                }
            }
        }
    }
    let cx = Ctx::new(pr);
    let (plan, extent) = match super::extent::selection_plan(&cx, &ids) {
        Some((pl, [lo, hi])) => (
            Value::u(pl),
            Value::Arr(vec![
                Value::Arr(vec![Value::f(rn(lo[0], 3)), Value::f(rn(lo[1], 3))]),
                Value::Arr(vec![Value::f(rn(hi[0], 3)), Value::f(rn(hi[1], 3))]),
            ]),
        ),
        None => (Value::Null, Value::Null),
    };
    Ok(jobj! {
        "extent" => extent,
        "ids" => Value::Arr(ids.iter().map(|i| Value::u(*i)).collect()),
        "library" => Value::Arr(lib.iter().map(|i| Value::u(*i)).collect()),
        "missing" => Value::Arr(missing),
        "plan" => plan,
    })
}

/// `measure {from, to}`.
pub fn cmd_measure(_s: &Session, p: &Value) -> Result<Value, String> {
    let empty = Value::obj();
    let p = if matches!(p, Value::Obj(_)) { p } else { &empty };
    let a = crate::commands::params::req_point(p, "measure", "from")?;
    let b = crate::commands::params::req_point(p, "measure", "to")?;
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    let mut ang = dy.atan2(dx).to_degrees();
    if ang < 0.0 {
        ang += 360.0;
    }
    Ok(jobj! {
        "angle" => rn(ang, 4),
        "dx" => r2(dx),
        "dy" => r2(dy),
        "length" => r2(dx.hypot(dy)),
    })
}

//! Where elements lie in plan: each one's extent as its level's plan draws it, a plan's extent of
//! everything it shows, and the size a view takes on a sheet at a scale.

use super::geo::{self, P};
use crate::json::Value;
use crate::project::Project;
use crate::readers::common::{self, Ctx};

/// A box in plan: its south-west and north-east corners.
pub type BoxP = [P; 2];

#[derive(Default, Clone, Copy)]
pub struct Bounds {
    pub b: Option<BoxP>,
}

impl Bounds {
    pub fn add(&mut self, p: P) {
        if !(p[0].is_finite() && p[1].is_finite()) {
            return;
        }
        self.b = Some(match self.b {
            None => [p, p],
            Some([lo, hi]) => [[lo[0].min(p[0]), lo[1].min(p[1])], [hi[0].max(p[0]), hi[1].max(p[1])]],
        });
    }
    pub fn add_box(&mut self, o: Option<BoxP>) {
        if let Some([lo, hi]) = o {
            self.add(lo);
            self.add(hi);
        }
    }
}

fn rect_around(a: P, b: P, half: f64) -> Vec<P> {
    let d = geo::unit(geo::sub(b, a));
    let n = geo::mul(geo::left(d), half);
    vec![geo::add(a, n), geo::add(b, n), geo::sub(b, n), geo::sub(a, n)]
}

fn rotated_rect(c: P, w: f64, d: f64, angle_deg: f64) -> Vec<P> {
    let (s, co) = angle_deg.to_radians().sin_cos();
    [[-w / 2.0, -d / 2.0], [w / 2.0, -d / 2.0], [w / 2.0, d / 2.0], [-w / 2.0, d / 2.0]]
        .iter()
        .map(|p| [c[0] + p[0] * co - p[1] * s, c[1] + p[0] * s + p[1] * co])
        .collect()
}

/// The points of an element's outline in plan (enough of them for its extent).
pub fn plan_points(cx: &Ctx, id: u64, e: &Value) -> Vec<P> {
    let pr = cx.pr;
    let cat = common::category(e);
    match cat {
        "wall" => match geo::wall(cx, id) {
            Some(w) => {
                let mut v = w.corners.to_vec();
                if let Some(a) = w.arc {
                    for off in [w.left, w.right] {
                        let o = a.offset(off);
                        for i in 0..=64 {
                            v.push(o.at(i as f64 / 64.0));
                        }
                    }
                }
                v
            }
            None => Vec::new(),
        },
        "floor" | "ceiling" | "roof" | "shaft" | "mass" => common::points(e.get("boundary").unwrap_or(&Value::Null)),
        "column" | "structuralcolumn" | "footing" => {
            let Some(at) = geo::pt(e.get("at")) else { return Vec::new() };
            let (w, d, round) = common::element_type(pr, e)
                .map(|(_, t)| {
                    (
                        common::num(t, "width").unwrap_or(0.0),
                        common::num(t, "depth").unwrap_or(0.0),
                        t.get("round").and_then(|r| r.as_bool()).unwrap_or(false),
                    )
                })
                .unwrap_or((0.0, 0.0, false));
            if round {
                return vec![[at[0] - w / 2.0, at[1] - w / 2.0], [at[0] + w / 2.0, at[1] + w / 2.0]];
            }
            rotated_rect(at, w, d, common::num(e, "angle").unwrap_or(0.0))
        }
        "beam" | "pipe" | "duct" | "conduit" | "cabletray" | "wire" | "downconductor" | "groundconductor" | "cable"
        | "stripfooting" => {
            let (Some(a), Some(b)) = (geo::pt(e.get("start")), geo::pt(e.get("end"))) else { return Vec::new() };
            let w = common::element_type(pr, e).and_then(|(_, t)| common::num(t, "width")).unwrap_or(0.0);
            if geo::dist(a, b) == 0.0 {
                return vec![[a[0] - w / 2.0, a[1] - w / 2.0], [a[0] + w / 2.0, a[1] + w / 2.0]];
            }
            rect_around(a, b, w / 2.0)
        }
        "roomseparator" | "section" | "elevation" | "grid" => {
            let mut v = Vec::new();
            for k in ["start", "end"] {
                if let Some(p) = geo::pt(e.get(k)) {
                    v.push(p);
                }
            }
            v
        }
        "railing" => common::points(e.get("path").unwrap_or(&Value::Null)),
        "room" | "text" | "spot" => geo::pt(e.get("point")).or_else(|| geo::pt(e.get("at"))).into_iter().collect(),
        "tag" => {
            let mut x = e.clone();
            super::annot::tag_view(cx, &mut x);
            geo::pt(x.get("at")).into_iter().collect()
        }
        "line" => line_points(e),
        "region" => {
            let mut v = Vec::new();
            for s in e.get("sketch").and_then(|s| s.as_arr()).cloned().unwrap_or_default() {
                v.extend(line_points(&s));
            }
            v
        }
        "stair" | "ramp" => {
            let w = common::num(e, "width").unwrap_or(0.0);
            let runs = e.get("runs").and_then(|r| r.as_arr()).cloned().unwrap_or_default();
            let mut v = Vec::new();
            for r in runs {
                let pts = common::points(&r);
                if pts.len() == 2 {
                    v.extend(rect_around(pts[0], pts[1], w / 2.0));
                }
            }
            if v.is_empty() {
                if let (Some(a), Some(b)) = (geo::pt(e.get("start")), geo::pt(e.get("end"))) {
                    v.extend(rect_around(a, b, w / 2.0));
                }
            }
            v
        }
        _ => Vec::new(),
    }
}

/// A detail line's (or a sketch line's) points, enough for its extent.
fn line_points(e: &Value) -> Vec<P> {
    let mut v = Vec::new();
    match super::details::shape(e) {
        "circle" => {
            if let (Some(c), Some(r)) = (geo::pt(e.get("centre")), common::num(e, "radius")) {
                v.push([c[0] - r, c[1] - r]);
                v.push([c[0] + r, c[1] + r]);
            }
        }
        "arc" => {
            if let (Some(a), Some(b), Some(t)) = (geo::pt(e.get("start")), geo::pt(e.get("end")), common::num(e, "arc")) {
                if let Some(arc) = geo::Arc::from_chord(a, b, t) {
                    for i in 0..=256 {
                        v.push(arc.at(i as f64 / 256.0));
                    }
                }
            }
        }
        "polyline" => v.extend(common::points(e.get("points").unwrap_or(&Value::Null))),
        "ellipse" | "partial ellipse" => {
            if let Some(c) = geo::pt(e.get("centre")) {
                let rr = e.get("radii").and_then(|r| r.as_arr()).cloned().unwrap_or_default();
                let rx = rr.first().and_then(|x| x.as_f64()).unwrap_or(0.0).abs();
                let ry = rr.get(1).and_then(|x| x.as_f64()).unwrap_or(0.0).abs();
                let span = geo::pt(e.get("span")).map(|s| (s[0], s[1]));
                v.extend(super::details::ellipse_points(c, rx, ry, common::num(e, "angle").unwrap_or(0.0), span));
            }
        }
        "spline" => {
            let ctrl = common::points(e.get("control").unwrap_or(&Value::Null));
            let knots = e.get("knots").and_then(|k| k.as_arr()).map(|a| a.iter().filter_map(|x| x.as_f64()).collect());
            v.extend(super::details::spline_points(&ctrl, knots));
        }
        "fitted spline" => {
            let pts = common::points(e.get("fit").unwrap_or(&Value::Null));
            v.extend(super::details::fit_points(&pts, None, None));
        }
        _ => {
            for k in ["start", "end"] {
                if let Some(p) = geo::pt(e.get(k)) {
                    v.push(p);
                }
            }
        }
    }
    v
}

/// Whether a plan of level `lv` (GUID) and view `view` (GUID: the level's own, or a plan view of it)
/// shows an element.
fn in_plan(pr: &Project, e: &Value, lv: &str, view: &str) -> bool {
    match common::category(e) {
        "grid" | "section" | "elevation" => true,
        "text" | "spot" | "line" | "region" | "detailgroup" | "repeatingdetail" => common::text(e, "view") == Some(view),
        "tag" => {
            let l = common::target(pr, e, "host").map(|(_, h)| super::annot::host_level(pr, h));
            matches!(l, Some(Value::Str(s)) if s == lv)
        }
        "roof" => true,
        "level" | "sheet" | "viewport" | "schedule" | "view3d" | "planview" | "door" | "window" | "rebar" | "link" | "pointcloud" => false,
        _ => common::text(e, "level") == Some(lv),
    }
}

/// Everything a plan shows: its extent.
pub fn plan_extent(cx: &Ctx, view_id: u64) -> Option<BoxP> {
    let pr = cx.pr;
    let lid = crate::model::level_of_view(pr, view_id)?;
    let lv = pr.guid_of(lid)?;
    let vg = pr.guid_of(view_id)?;
    let mut b = Bounds::default();
    for (id, e) in &pr.elements {
        if !in_plan(pr, e, &lv, &vg) {
            continue;
        }
        if common::category(e) == "dimension" {
            continue;
        }
        for p in plan_points(cx, *id, e) {
            b.add(p);
        }
    }
    b.b
}

/// Rounds a paper length up to the 0.2 mm a sheet is laid out on.
fn up5(x: f64) -> f64 {
    let k = (x * 5.0 - 1e-6).ceil();
    k / 5.0
}

/// The size a view takes on a sheet at 1 : `scale`, paper mm.
pub fn viewport_size(cx: &Ctx, vid: u64, v: &Value, scale: f64, _vp: &Value) -> Option<P> {
    let scale = if scale > 0.0 { scale } else { 100.0 };
    match common::category(v) {
        "level" | "planview" => {
            let [lo, hi] = plan_extent(cx, vid).unwrap_or([[0.0, 0.0], [10000.0, 10000.0]]);
            let w = super::common_round3(hi[0] - lo[0]);
            let h = super::common_round3(hi[1] - lo[1]);
            Some([up5(w / scale + 24.0), up5(h / scale + 24.0)])
        }
        _ => None,
    }
}

/// The plan that shows the elements of a selection, and where they lie in it.
pub fn selection_plan(cx: &Ctx, ids: &[u64]) -> Option<(u64, BoxP)> {
    let pr = cx.pr;
    let mut plan = None;
    let mut b = Bounds::default();
    for id in ids {
        let e = pr.el(*id)?;
        let lv = match common::category(e) {
            "door" | "window" | "tag" => {
                let h = if common::category(e) == "tag" { common::target(pr, e, "host").map(|(_, h)| h) } else { Some(e) };
                h.map(|h| super::annot::host_level(pr, h)).and_then(|v| v.as_str().map(|s| s.to_string()))
            }
            _ => common::text(e, "level").map(|s| s.to_string()).or_else(|| {
                super::annot::view_level(pr, common::text(e, "view")).as_str().map(|s| s.to_string())
            }),
        };
        let Some(lv) = lv else { continue };
        let Some(lid) = pr.find_guid(&lv) else { continue };
        if plan.is_none() {
            plan = Some(lid);
        }
        for p in plan_points(cx, *id, e) {
            b.add(p);
        }
    }
    Some((plan?, b.b?))
}

